package com.bank.patterns.model;

import java.util.Optional;

public class BadCustomer {

    private String customerId;
    private String name;

    // ❌ ANTI-PATTERN 1: Optional as field — not Serializable, JPA breaks
    private Optional<String> middleName = Optional.empty();

    // ❌ ANTI-PATTERN 2: Optional as field
    private Optional<String> phone = Optional.empty();

    public BadCustomer(String customerId, String name) {
        this.customerId = customerId;
        this.name = name;
    }

    // ❌ ANTI-PATTERN 3: Optional as parameter
    public void setMiddleName(Optional<String> middleName) {
        this.middleName = middleName;
        // What if caller passes null? NPE on the Optional itself!
    }

    // ❌ ANTI-PATTERN 4: .get() without check
    public String getMiddleNameUnsafe() {
        return middleName.get();  // 💥 NoSuchElementException if empty!
    }

    public String getCustomerId() { return customerId; }
    public String getName() { return name; }
    public Optional<String> getMiddleName() { return middleName; }
}
