// ✅ CORRECT PATTERNS — Optional only as return type
package com.bank.patterns.model;

import java.util.Optional;

public class GoodCustomer {

    private final String customerId;
    private final String name;
    private final String middleName;   // nullable — stored as plain field
    private final String phone;        // nullable — stored as plain field

    public GoodCustomer(String customerId, String name, String middleName, String phone) {
        this.customerId = customerId;
        this.name = name;
        this.middleName = middleName;  // can be null — that's fine
        this.phone = phone;            // can be null — that's fine
    }

    // ✅ CORRECT: Optional as RETURN TYPE — converts nullable field at boundary
    public Optional<String> getMiddleName() {
        return Optional.ofNullable(middleName);
    }

    public Optional<String> getPhone() {
        return Optional.ofNullable(phone);
    }

    // ✅ CORRECT: method overloading instead of Optional parameter
    public String getDisplayName() {
        return getMiddleName()
            .map(m -> name + " " + m)
            .orElse(name);
    }

    // ✅ NON-OPTIONAL getters for frameworks (JPA, Jackson)
    public String getCustomerId() { return customerId; }
    public String getName() { return name; }
    public String getMiddleNameRaw() { return middleName; }  // for serialization
}
