// ─── File: src/main/java/com/bank/patterns/service/PatternDemoService.java ───
package com.bank.patterns.service;

import com.bank.patterns.dto.PatternReport;
import com.bank.patterns.model.*;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.util.*;

@Service
@Slf4j
public class PatternDemoService {

    public PatternReport demonstratePatterns() {
        List<String> antiPatterns = new ArrayList<>();
        List<String> correctPatterns = new ArrayList<>();

        // ═══ ANTI-PATTERN 1: Optional field ═══
        antiPatterns.add("❌ Optional<String> middleName as FIELD — not Serializable, "
            + "JPA can't persist, 16 bytes overhead per instance");

        // ═══ ANTI-PATTERN 2: Optional parameter ═══
        BadCustomer bad = new BadCustomer("CUST-001", "Rajesh");
        bad.setMiddleName(Optional.of("Kumar"));  // awkward caller syntax!
        // bad.setMiddleName(null);  // would cause NPE on the Optional!
        antiPatterns.add("❌ setMiddleName(Optional<String>) — caller must wrap, null Optional = NPE");

        // ═══ ANTI-PATTERN 3: .get() without check ═══
        BadCustomer badNoMiddle = new BadCustomer("CUST-002", "Priya");
        try {
            String middle = badNoMiddle.getMiddleNameUnsafe();  // .get() on empty!
        } catch (NoSuchElementException e) {
            antiPatterns.add("❌ .get() without check → NoSuchElementException: " + e.getMessage());
        }

        // ═══ ANTI-PATTERN 4: Optional in collection ═══
        List<Optional<String>> badList = List.of(
            Optional.of("Trade1"), Optional.empty(), Optional.of("Trade3"));
        antiPatterns.add("❌ List<Optional<String>> — bizarre, use List<String> without nulls");

        // ═══ CORRECT PATTERN 1: Optional as return type ═══
        GoodCustomer good = new GoodCustomer("CUST-001", "Rajesh", "Kumar", "+91-9876543210");
        String display = good.getMiddleName()
            .map(m -> good.getName() + " " + m)
            .orElse(good.getName());
        correctPatterns.add("✅ getMiddleName() returns Optional<String> — " + display);

        // ═══ CORRECT PATTERN 2: nullable field + Optional getter ═══
        GoodCustomer noMiddle = new GoodCustomer("CUST-002", "Priya", null, null);
        String phone = noMiddle.getPhone().orElse("Not provided");
        correctPatterns.add("✅ Nullable field + Optional getter: phone = " + phone);

        // ═══ CORRECT PATTERN 3: orElseThrow instead of .get() ═══
        GoodCustomer existing = new GoodCustomer("CUST-001", "Rajesh", "Kumar", null);
        String middle = existing.getMiddleName()
            .orElseThrow(() -> new IllegalStateException("Middle name required!"));
        correctPatterns.add("✅ orElseThrow instead of .get(): " + middle);

        // ═══ CORRECT PATTERN 4: flat collection instead of Optional collection ═══
        List<String> goodList = List.of("Trade1", "Trade3");  // no nulls, no Optionals
        correctPatterns.add("✅ List<String> without nulls: " + goodList);

        return new PatternReport(antiPatterns, correctPatterns,
            "Optional = return type ONLY. Not fields. Not params. Not collections. Never .get().");
    }
}
