// ─── File: src/test/java/com/bank/patterns/OptionalAntiPatternTest.java ───
package com.bank.patterns;

import com.bank.patterns.model.GoodCustomer;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class OptionalAntiPatternTest {

    @Test
    void getWithoutCheckThrows() {
        assertThatThrownBy(() -> Optional.empty().get())
            .isInstanceOf(NoSuchElementException.class);
    }

    @Test
    void orElseThrowIsBetterThanGet() {
        assertThatThrownBy(() ->
            Optional.empty().orElseThrow(() -> new IllegalArgumentException("Not found!")))
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessage("Not found!");
    }

    @Test
    void optionalIsNotSerializable() {
        // Optional does NOT implement Serializable
        assertThat(java.io.Serializable.class.isAssignableFrom(Optional.class)).isFalse();
    }

    @Test
    void nullableFieldWithOptionalGetter() {
        GoodCustomer customer = new GoodCustomer("C1", "Rajesh", null, null);
        assertThat(customer.getMiddleName()).isEmpty();       // Optional return
        assertThat(customer.getMiddleNameRaw()).isNull();      // raw for frameworks
        assertThat(customer.getPhone().orElse("N/A")).isEqualTo("N/A");
    }

    @Test
    void displayNameWithAndWithoutMiddle() {
        GoodCustomer with = new GoodCustomer("C1", "Rajesh", "Kumar", null);
        GoodCustomer without = new GoodCustomer("C2", "Priya", null, null);

        assertThat(with.getDisplayName()).isEqualTo("Rajesh Kumar");
        assertThat(without.getDisplayName()).isEqualTo("Priya");
    }

    @Test
    void useCollectionWithoutOptionals() {
        // ❌ BAD: List<Optional<String>>
        // ✅ GOOD: filter nulls at source
        List<String> names = Arrays.asList("Rajesh", null, "Priya", null, "Amit");
        List<String> clean = names.stream().filter(Objects::nonNull).toList();
        assertThat(clean).containsExactly("Rajesh", "Priya", "Amit");
    }
}
